#include <string.h>
#include <time.h>

#define MAX_MSG_LEN 256

/**
Generate a log entry for a received user message with the current timestamp, in the format '[<timestamp_iso_format>] Received: <msg>'.

@param msg The user message received.

@return The log entry for the received message.
*/
char* generate_receive_log(const char *msg) {
    char timestamp_buffer[30]; // Sufficient for ISO 8601 format like "YYYY-MM-DDTHH:MM:SSZ"
    // Calculate the maximum possible length of the log entry:
    // Timestamp (e.g., "YYYY-MM-DDTHH:MM:SSZ") + "[] Received: " + MAX_MSG_LEN + null terminator
    size_t max_log_len = sizeof("YYYY-MM-DDTHH:MM:SSZ") + strlen("[] Received: ") + MAX_MSG_LEN + 1;
    char *log_entry = (char *)malloc(max_log_len);

    if (log_entry == NULL) {
        // In a real-world scenario, this should be handled by the caller.
        // Returning NULL indicates allocation failure.
        return NULL;
    }

    // Get current time
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now); // Use gmtime for UTC

    // Format timestamp in ISO 8601 format (YYYY-MM-DDTHH:MM:SSZ)
    strftime(timestamp_buffer, sizeof(timestamp_buffer), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Construct the log entry using snprintf for safety
    snprintf(log_entry, max_log_len, "[%s] Received: %s", timestamp_buffer, msg);

    return log_entry;
}
